-- 2026 Ohio State High School Qualifier #4: relay 4x200M Relay place 17
SET @pid = (SELECT MIN(p.Id) FROM Performances p JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE p.AthleteId IS NULL AND m.Name=N'2026 Ohio State High School Qualifier #4' AND CAST(m.Date AS date)='2026-02-07' AND e.Name=N'4x200M Relay' AND e.Gender=1 AND ABS(p.TimeSeconds-102.99)<0.06);
